subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "fund": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9._-]+$",
      "type": "string"
    },
    "period": {
      "maxLength": 16,
      "pattern": "^[0-9]{4}-Q[1-4]$",
      "type": "string"
    },
    "statement": {
      "description": "Parsed LP capital account by section: commitments, calls, distributions, fees, NAV",
      "type": "object"
    }
  },
  "required": [
    "fund",
    "period",
    "statement"
  ],
  "type": "object"
}
